import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import { createStaticLookupSearchConfig } from './createStaticLookupSearchConfig';
import { masterService } from '../../services/master/masterService';
import type { PaymentChannelDto } from '../../services/master/models';

export function dedupePaymentChannels(channels: PaymentChannelDto[]): PaymentChannelDto[] {
  const seen = new Set<string>();
  return channels.filter(ch => {
    const key = (ch.code ?? '').trim().toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

/** Lookup kênh TT cho form danh mục TK ngân hàng. */
export function createPaymentChannelSearchConfig(): SearchInputConfig<PaymentChannelDto> {
  return createStaticLookupSearchConfig({
    loadItems: async () => {
      const rows = await masterService.getPaymentChannels({ isActive: true });
      return dedupePaymentChannels(rows);
    },
    getKey: ch => ch.code,
    getCode: ch => ch.code,
    getName: ch => ch.name,
    getFilterText: ch => `${ch.code} ${ch.name}`,
  });
}
